/**
 * Utility functions for user preferences and settings
 */

// Local storage keys
const STORAGE_KEYS = {
  THEME: 'zoom_theme',
  AUDIO_SETTINGS: 'zoom_audio_settings',
  VIDEO_SETTINGS: 'zoom_video_settings',
  NOTIFICATION_SETTINGS: 'zoom_notification_settings',
  RECENT_MEETINGS: 'zoom_recent_meetings',
  USER_PREFERENCES: 'zoom_user_preferences',
};

/**
 * Saves a value to local storage
 * @param {string} key - Storage key
 * @param {any} value - Value to store
 */
const saveToStorage = (key, value) => {
  try {
    const serializedValue = JSON.stringify(value);
    localStorage.setItem(key, serializedValue);
  } catch (error) {
    console.error('Error saving to local storage:', error);
  }
};

/**
 * Retrieves a value from local storage
 * @param {string} key - Storage key
 * @param {any} defaultValue - Default value if key doesn't exist
 * @returns {any} Retrieved value or default value
 */
const getFromStorage = (key, defaultValue = null) => {
  try {
    const serializedValue = localStorage.getItem(key);
    if (serializedValue === null) {
      return defaultValue;
    }
    return JSON.parse(serializedValue);
  } catch (error) {
    console.error('Error retrieving from local storage:', error);
    return defaultValue;
  }
};

/**
 * Saves theme preference
 * @param {string} theme - Theme value ('light' or 'dark')
 */
export const saveThemePreference = (theme) => {
  saveToStorage(STORAGE_KEYS.THEME, theme);
};

/**
 * Gets theme preference
 * @returns {string} Theme value ('light' or 'dark')
 */
export const getThemePreference = () => {
  return getFromStorage(STORAGE_KEYS.THEME, 'light');
};

/**
 * Default audio settings
 */
const DEFAULT_AUDIO_SETTINGS = {
  microphoneEnabled: true,
  speakerEnabled: true,
  microphoneDevice: null,
  speakerDevice: null,
  autoJoinAudio: true,
  noiseSuppression: true,
  echoCancellation: true,
};

/**
 * Saves audio settings
 * @param {Object} settings - Audio settings object
 */
export const saveAudioSettings = (settings) => {
  const currentSettings = getAudioSettings();
  saveToStorage(STORAGE_KEYS.AUDIO_SETTINGS, {
    ...currentSettings,
    ...settings,
  });
};

/**
 * Gets audio settings
 * @returns {Object} Audio settings
 */
export const getAudioSettings = () => {
  return getFromStorage(STORAGE_KEYS.AUDIO_SETTINGS, DEFAULT_AUDIO_SETTINGS);
};

