/**
 * Adds a meeting to recent meetings list
 * @param {Object} meeting - Meeting object
 * @param {number} maxItems - Maximum number of recent meetings to store
 */
export const addToRecentMeetings = (meeting, maxItems = 10) => {
  if (!meeting || !meeting.code) return;
  
  const recentMeetings = getRecentMeetings();
  
  // Remove if already exists
  const filteredMeetings = recentMeetings.filter(m => m.code !== meeting.code);
  
  // Add to beginning of array
  const updatedMeetings = [meeting, ...filteredMeetings].slice(0, maxItems);
  
  saveToStorage(STORAGE_KEYS.RECENT_MEETINGS, updatedMeetings);
};

/**
 * Gets recent meetings list
 * @returns {Array} Recent meetings
 */
export const getRecentMeetings = () => {
  return getFromStorage(STORAGE_KEYS.RECENT_MEETINGS, []);
};

/**
 * Default user preferences
 */
const DEFAULT_USER_PREFERENCES = {
  language: 'en',
  timeFormat: '12h',
  dateFormat: 'MM/DD/YYYY',
  startView: 'home',
  accessibility: {
    highContrast: false,
    largeText: false,
    reducedMotion: false,
  },
};

/**
 * Saves user preferences
 * @param {Object} preferences - User preferences object
 */
export const saveUserPreferences = (preferences) => {
  const currentPreferences = getUserPreferences();
  saveToStorage(STORAGE_KEYS.USER_PREFERENCES, {
    ...currentPreferences,
    ...preferences,
  });
};

/**
 * Gets user preferences
 * @returns {Object} User preferences
 */
export const getUserPreferences = () => {
  return getFromStorage(STORAGE_KEYS.USER_PREFERENCES, DEFAULT_USER_PREFERENCES);
};

/**
 * Clears all user preferences and settings
 */
export const clearAllPreferences = () => {
  Object.values(STORAGE_KEYS).forEach(key => {
    localStorage.removeItem(key);
  });
};