/**
 * Utility functions for time formatting and manipulation
 */

/**
 * Formats a duration in seconds to a human-readable string (HH:MM:SS)
 * @param {number} seconds - The duration in seconds
 * @returns {string} Formatted time string
 */
export const formatDuration = (seconds) => {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = Math.floor(seconds % 60);

  const formattedHours = hours > 0 ? `${hours.toString().padStart(2, '0')}:` : '';
  const formattedMinutes = `${minutes.toString().padStart(2, '0')}`;
  const formattedSeconds = `${secs.toString().padStart(2, '0')}`;

  return `${formattedHours}${formattedMinutes}:${formattedSeconds}`;
};

/**
 * Formats a Date object to a time string (HH:MM AM/PM)
 * @param {Date} date - The date object to format
 * @returns {string} Formatted time string
 */
export const formatTime = (date) => {
  if (!(date instanceof Date)) {
    date = new Date(date);
  }
  
  return date.toLocaleTimeString('en-US', {
    hour: '2-digit',
    minute: '2-digit',
    hour12: true
  });
};

/**
 * Formats a Date object to a date string (MM/DD/YYYY)
 * @param {Date} date - The date object to format
 * @returns {string} Formatted date string
 */
export const formatDate = (date) => {
  if (!(date instanceof Date)) {
    date = new Date(date);
  }
  
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  });
};

/**
 * Formats a Date object to a full datetime string (MM/DD/YYYY, HH:MM AM/PM)
 * @param {Date} date - The date object to format
 * @returns {string} Formatted datetime string
 */
export const formatDateTime = (date) => {
  if (!(date instanceof Date)) {
    date = new Date(date);
  }
  
  return `${formatDate(date)}, ${formatTime(date)}`;
};

/**
 * Calculates the time difference between two dates in minutes
 * @param {Date} date1 - The first date
 * @param {Date} date2 - The second date
 * @returns {number} Time difference in minutes
 */
export const getTimeDifferenceInMinutes = (date1, date2) => {
  if (!(date1 instanceof Date)) {
    date1 = new Date(date1);
  }
  if (!(date2 instanceof Date)) {
    date2 = new Date(date2);
  }
  
  const diffMs = Math.abs(date2 - date1);
  return Math.floor(diffMs / (1000 * 60));
};

/**
 * Checks if a meeting is happening now (current time is between start and end time)
 * @param {Date} startTime - Meeting start time
 * @param {Date} endTime - Meeting end time
 * @returns {boolean} True if meeting is happening now
 */
export const isMeetingNow = (startTime, endTime) => {
  const now = new Date();
  if (!(startTime instanceof Date)) {
    startTime = new Date(startTime);
  }
  if (!(endTime instanceof Date)) {
    endTime = new Date(endTime);
  }
  
  return now >= startTime && now <= endTime;
};

/**
 * Returns a human-readable string for how long until a meeting starts
 * @param {Date} startTime - Meeting start time
 * @returns {string} Human-readable time until meeting
 */
export const getTimeUntilMeeting = (startTime) => {
  if (!(startTime instanceof Date)) {
    startTime = new Date(startTime);
  }
  
  const now = new Date();
  if (startTime <= now) {
    return 'Now';
  }
  
  const diffMs = startTime - now;
  const diffMins = Math.floor(diffMs / (1000 * 60));
  const diffHours = Math.floor(diffMins / 60);
  const diffDays = Math.floor(diffHours / 24);
  
  if (diffDays > 0) {
    return `${diffDays} day${diffDays > 1 ? 's' : ''}`;
  } else if (diffHours > 0) {
    return `${diffHours} hour${diffHours > 1 ? 's' : ''}`;
  } else {
    return `${diffMins} minute${diffMins > 1 ? 's' : ''}`;
  }
};