import React, { useState, useEffect } from 'react';
import { Box, Typography, Button, Paper, Stack, Divider } from '@mui/material';
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

// Import utility functions
import {
  formatTime,
  formatDate,
  formatDateTime,
  getTimeUntilMeeting,
  generateMeetingCode,
  showSuccessNotification,
  showInfoNotification,
  showWarningNotification,
  showErrorNotification,
  getThemePreference,
  saveThemePreference,
  isScreenShareSupported,
  isRecordingSupported
} from '../utils';

/**
 * Component to demonstrate utility functions
 */
const UtilsDemo = () => {
  const [currentTime, setCurrentTime] = useState(new Date());
  const [meetingCode, setMeetingCode] = useState('');
  
  // Update current time every second
  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentTime(new Date());
    }, 1000);
    
    return () => clearInterval(timer);
  }, []);
  
  // Generate a meeting code
  const handleGenerateCode = () => {
    const code = generateMeetingCode(8);
    setMeetingCode(code);
    showSuccessNotification(`Meeting code generated: ${code}`);
  };
  
  // Show different types of notifications
  const handleShowNotifications = () => {
    showSuccessNotification('This is a success notification');
    setTimeout(() => {
      showInfoNotification('This is an info notification');
    }, 1000);
    setTimeout(() => {
      showWarningNotification('This is a warning notification');
    }, 2000);
    setTimeout(() => {
      showErrorNotification('This is an error notification');
    }, 3000);
  };
  
  // Toggle theme
  const handleToggleTheme = () => {
    const currentTheme = getThemePreference();
    const newTheme = currentTheme === 'light' ? 'dark' : 'light';
    saveThemePreference(newTheme);
    showInfoNotification(`Theme changed to ${newTheme}`);
    // Reload page to apply theme change
    window.location.reload();
  };
  
  // Check browser capabilities
  const screenShareSupported = isScreenShareSupported();
  const recordingSupported = isRecordingSupported();
  
  // Meeting example
  const meetingStartTime = new Date();
  meetingStartTime.setHours(meetingStartTime.getHours() + 2); // 2 hours from now
  
  const meetingEndTime = new Date(meetingStartTime);
  meetingEndTime.setHours(meetingEndTime.getHours() + 1); // 1 hour meeting
  
  return (
    <Box sx={{ p: 3, maxWidth: 800, mx: 'auto' }}>
      <ToastContainer />
      
      <Typography variant="h4" gutterBottom>
        Utility Functions Demo
      </Typography>
      
      <Stack spacing={3}>
        <Paper elevation={3} sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Time Utilities
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body1">
            Current Time: {formatTime(currentTime)}
          </Typography>
          <Typography variant="body1">
            Current Date: {formatDate(currentTime)}
          </Typography>
          <Typography variant="body1">
            Current DateTime: {formatDateTime(currentTime)}
          </Typography>
          <Typography variant="body1">
            Time Until Meeting: {getTimeUntilMeeting(meetingStartTime)}
          </Typography>
        </Paper>
        
        <Paper elevation={3} sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Meeting Utilities
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body1" gutterBottom>
            Meeting Code: {meetingCode || 'None generated yet'}
          </Typography>
          <Button 
            variant="contained" 
            onClick={handleGenerateCode}
            sx={{ mr: 2 }}
          >
            Generate Meeting Code
          </Button>
        </Paper>
        
        <Paper elevation={3} sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Notification Utilities
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Button 
            variant="contained" 
            onClick={handleShowNotifications}
            sx={{ mr: 2 }}
          >
            Show Notifications
          </Button>
        </Paper>
        
        <Paper elevation={3} sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Preferences Utilities
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body1" gutterBottom>
            Current Theme: {getThemePreference()}
          </Typography>
          <Button 
            variant="contained" 
            onClick={handleToggleTheme}
            sx={{ mr: 2 }}
          >
            Toggle Theme
          </Button>
        </Paper>
        
        <Paper elevation={3} sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Browser Capabilities
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Typography variant="body1">
            Screen Share Supported: {screenShareSupported ? 'Yes' : 'No'}
          </Typography>
          <Typography variant="body1">
            Recording Supported: {recordingSupported ? 'Yes' : 'No'}
          </Typography>
        </Paper>
      </Stack>
    </Box>
  );
};

export default UtilsDemo;