/**
 * Utility functions for screen sharing
 */

/**
 * Starts screen sharing
 * @returns {Promise<MediaStream|null>} Screen share stream or null if failed
 */
export const startScreenShare = async () => {
  try {
    const mediaDevices = navigator.mediaDevices;
    
    if (!mediaDevices.getDisplayMedia) {
      throw new Error('Screen sharing not supported in this browser');
    }
    
    const stream = await mediaDevices.getDisplayMedia({
      video: {
        cursor: 'always',
        displaySurface: 'monitor',
      },
      audio: false,
    });
    
    // Add event listener for when user stops sharing via browser UI
    const videoTrack = stream.getVideoTracks()[0];
    if (videoTrack) {
      videoTrack.addEventListener('ended', () => {
        // Dispatch custom event that can be listened to by components
        const event = new CustomEvent('screensharestopped');
        window.dispatchEvent(event);
      });
    }
    
    return stream;
  } catch (error) {
    console.error('Error starting screen share:', error);
    return null;
  }
};

/**
 * Stops screen sharing
 * @param {MediaStream} stream - Screen share stream to stop
 */
export const stopScreenShare = (stream) => {
  if (!stream) return;
  
  stream.getTracks().forEach(track => {
    track.stop();
  });
};

/**
 * Checks if screen sharing is supported in the current browser
 * @returns {boolean} True if screen sharing is supported
 */
export const isScreenShareSupported = () => {
  return !!(navigator.mediaDevices && navigator.mediaDevices.getDisplayMedia);
};

/**
 * Gets screen sharing constraints based on quality setting
 * @param {string} quality - Quality setting ('low', 'medium', 'high')
 * @returns {Object} Screen sharing constraints
 */
export const getScreenShareConstraints = (quality = 'medium') => {
  const constraints = {
    video: {
      cursor: 'always',
    },
    audio: false,
  };
  
  switch (quality) {
    case 'low':
      constraints.video.width = { ideal: 1280 };
      constraints.video.height = { ideal: 720 };
      constraints.video.frameRate = { max: 15 };
      break;
    case 'medium':
      constraints.video.width = { ideal: 1920 };
      constraints.video.height = { ideal: 1080 };
      constraints.video.frameRate = { max: 30 };
      break;
    case 'high':
      constraints.video.width = { ideal: 3840 };
      constraints.video.height = { ideal: 2160 };
      constraints.video.frameRate = { max: 60 };
      break;
    default:
      // Use medium as default
      constraints.video.width = { ideal: 1920 };
      constraints.video.height = { ideal: 1080 };
      constraints.video.frameRate = { max: 30 };
  }
  
  return constraints;
};

/**
 * Captures a screenshot from the screen share stream
 * @param {MediaStream} stream - Screen share stream
 * @returns {Promise<string|null>} Screenshot as data URL or null if failed
 */
export const captureScreenshot = async (stream) => {
  if (!stream) return null;
  
  try {
    const videoTrack = stream.getVideoTracks()[0];
    if (!videoTrack) return null;
    
    const imageCapture = new ImageCapture(videoTrack);
    const bitmap = await imageCapture.grabFrame();
    
    // Create canvas to convert ImageBitmap to data URL
    const canvas = document.createElement('canvas');
    canvas.width = bitmap.width;
    canvas.height = bitmap.height;
    
    const context = canvas.getContext('2d');
    context.drawImage(bitmap, 0, 0, bitmap.width, bitmap.height);
    
    return canvas.toDataURL('image/jpeg', 0.8);
  } catch (error) {
    console.error('Error capturing screenshot:', error);
    return null;
  }
};

/**
 * Checks if audio sharing is supported for screen sharing
 * @returns {boolean} True if audio sharing is supported
 */
export const isAudioShareSupported = () => {
  // Chrome supports audio sharing since version 74
  const isChrome = /Chrome/.test(navigator.userAgent) && /Google Inc/.test(navigator.vendor);
  if (isChrome) {
    const match = navigator.userAgent.match(/Chrome\/([\d.]+)/);
    if (match && match[1]) {
      const version = parseInt(match[1], 10);
      return version >= 74;
    }
  }
  
  return false;
};

/**
 * Starts screen sharing with audio (if supported)
 * @returns {Promise<MediaStream|null>} Screen share stream with audio or null if failed
 */
export const startScreenShareWithAudio = async () => {
  try {
    const mediaDevices = navigator.mediaDevices;
    
    if (!mediaDevices.getDisplayMedia) {
      throw new Error('Screen sharing not supported in this browser');
    }
    
    const constraints = {
      video: {
        cursor: 'always',
      },
      audio: isAudioShareSupported(),
    };
    
    const stream = await mediaDevices.getDisplayMedia(constraints);
    
    // Add event listener for when user stops sharing via browser UI
    const videoTrack = stream.getVideoTracks()[0];
    if (videoTrack) {
      videoTrack.addEventListener('ended', () => {
        // Dispatch custom event that can be listened to by components
        const event = new CustomEvent('screensharestopped');
        window.dispatchEvent(event);
      });
    }
    
    return stream;
  } catch (error) {
    console.error('Error starting screen share with audio:', error);
    return null;
  }
};