/**
 * Utility functions for meeting management
 */

import { formatDateTime, getTimeUntilMeeting, isMeetingNow } from './timeUtils';

/**
 * Generates a random meeting code
 * @param {number} length - Length of the meeting code
 * @returns {string} Generated meeting code
 */
export const generateMeetingCode = (length = 10) => {
  const characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
  let result = '';
  const charactersLength = characters.length;
  
  for (let i = 0; i < length; i++) {
    result += characters.charAt(Math.floor(Math.random() * charactersLength));
  }
  
  return result;
};

/**
 * Formats meeting details for display
 * @param {Object} meeting - Meeting object
 * @returns {Object} Formatted meeting details
 */
export const formatMeetingDetails = (meeting) => {
  if (!meeting) return null;
  
  return {
    ...meeting,
    formattedStartTime: formatDateTime(meeting.startTime),
    formattedEndTime: formatDateTime(meeting.endTime),
    timeUntil: getTimeUntilMeeting(meeting.startTime),
    isHappeningNow: isMeetingNow(meeting.startTime, meeting.endTime)
  };
};

/**
 * Sorts meetings by start time (ascending)
 * @param {Array} meetings - Array of meeting objects
 * @returns {Array} Sorted meetings
 */
export const sortMeetingsByStartTime = (meetings) => {
  if (!meetings || !Array.isArray(meetings)) return [];
  
  return [...meetings].sort((a, b) => {
    const dateA = new Date(a.startTime);
    const dateB = new Date(b.startTime);
    return dateA - dateB;
  });
};

/**
 * Filters meetings by status (upcoming, ongoing, past)
 * @param {Array} meetings - Array of meeting objects
 * @param {string} status - Status to filter by ('upcoming', 'ongoing', 'past')
 * @returns {Array} Filtered meetings
 */
export const filterMeetingsByStatus = (meetings, status) => {
  if (!meetings || !Array.isArray(meetings)) return [];
  
  const now = new Date();
  
  switch (status) {
    case 'upcoming':
      return meetings.filter(meeting => new Date(meeting.startTime) > now);
    case 'ongoing':
      return meetings.filter(meeting => {
        const startTime = new Date(meeting.startTime);
        const endTime = new Date(meeting.endTime);
        return now >= startTime && now <= endTime;
      });
    case 'past':
      return meetings.filter(meeting => new Date(meeting.endTime) < now);
    default:
      return meetings;
  }
};

/**
 * Checks if a meeting code is valid
 * @param {string} code - Meeting code to validate
 * @returns {boolean} True if code is valid
 */
export const isValidMeetingCode = (code) => {
  if (!code || typeof code !== 'string') return false;
  
  // Meeting code should be alphanumeric and at least 6 characters
  return /^[a-zA-Z0-9]{6,}$/.test(code);
};

/**
 * Creates a calendar event URL for a meeting
 * @param {Object} meeting - Meeting object with title, startTime, endTime, and description
 * @returns {string} Calendar event URL
 */
export const createCalendarEventUrl = (meeting) => {
  if (!meeting) return '';
  
  const startTime = new Date(meeting.startTime);
  const endTime = new Date(meeting.endTime);
  
  // Format dates for Google Calendar
  const formatDateForCalendar = (date) => {
    return date.toISOString().replace(/-|:|\.\d+/g, '');
  };
  
  const startTimeFormatted = formatDateForCalendar(startTime);
  const endTimeFormatted = formatDateForCalendar(endTime);
  
  // Create Google Calendar URL
  const baseUrl = 'https://calendar.google.com/calendar/render';
  const params = new URLSearchParams({
    action: 'TEMPLATE',
    text: meeting.title || 'Video Meeting',
    dates: `${startTimeFormatted}/${endTimeFormatted}`,
    details: meeting.description || `Join meeting with code: ${meeting.code}`,
    location: `https://yourdomain.com/meet/${meeting.code}`
  });
  
  return `${baseUrl}?${params.toString()}`;
};