import React, { useState } from 'react';
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  TextField,
  Box,
  Typography,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Chip,
  IconButton,
  CircularProgress,
  Alert,
  Snackbar
} from '@mui/material';
import { DateTimePicker } from '@mui/x-date-pickers/DateTimePicker';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import CloseIcon from '@mui/icons-material/Close';
import ContentCopyIcon from '@mui/icons-material/ContentCopy';
import EventIcon from '@mui/icons-material/Event';
import AccessTimeIcon from '@mui/icons-material/AccessTime';
import PersonAddIcon from '@mui/icons-material/PersonAdd';
import { format } from 'date-fns';

const ScheduleMeeting = ({ open, onClose, onSchedule }) => {
  const [meetingTitle, setMeetingTitle] = useState('');
  const [meetingDate, setMeetingDate] = useState(new Date());
  const [duration, setDuration] = useState(30);
  const [participants, setParticipants] = useState([]);
  const [newParticipant, setNewParticipant] = useState('');
  const [loading, setLoading] = useState(false);
  const [meetingCode, setMeetingCode] = useState('');
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  const handleSchedule = async () => {
    if (!meetingTitle.trim()) {
      setSnackbar({
        open: true,
        message: 'Please enter a meeting title',
        severity: 'error'
      });
      return;
    }

    setLoading(true);
    
    try {
      // Generate a random meeting code
      const generatedCode = Math.random().toString(36).substring(2, 10);
      setMeetingCode(generatedCode);
      
      // In a real implementation, this would save to the backend
      // For now, we'll simulate a successful API call
      setTimeout(() => {
        setLoading(false);
        
        // Call the onSchedule callback with meeting details
        onSchedule({
          title: meetingTitle,
          date: meetingDate,
          duration,
          participants,
          meetingCode: generatedCode
        });
        
        setSnackbar({
          open: true,
          message: 'Meeting scheduled successfully!',
          severity: 'success'
        });
      }, 1500);
    } catch (error) {
      setLoading(false);
      setSnackbar({
        open: true,
        message: 'Failed to schedule meeting',
        severity: 'error'
      });
    }
  };

  const handleAddParticipant = () => {
    if (newParticipant.trim() && !participants.includes(newParticipant.trim())) {
      setParticipants([...participants, newParticipant.trim()]);
      setNewParticipant('');
    }
  };

  const handleRemoveParticipant = (participant) => {
    setParticipants(participants.filter(p => p !== participant));
  };

  const handleCopyMeetingCode = () => {
    navigator.clipboard.writeText(meetingCode);
    setSnackbar({
      open: true,
      message: 'Meeting code copied to clipboard!',
      severity: 'success'
    });
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  return (
    <>
      <Dialog 
        open={open} 
        onClose={loading ? null : onClose}
        maxWidth="md"
        fullWidth
        PaperProps={{
          sx: {
            borderRadius: 2,
            boxShadow: 24
          }
        }}
      >
        <DialogTitle sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <Typography variant="h5" component="div" sx={{ fontWeight: 'bold' }}>
            Schedule a New Meeting
          </Typography>
          {!loading && (
            <IconButton onClick={onClose} size="small">
              <CloseIcon />
            </IconButton>
          )}
        </DialogTitle>
        
        <DialogContent dividers>
          {meetingCode ? (
            <Box sx={{ textAlign: 'center', py: 3 }}>
              <Typography variant="h6" gutterBottom>
                Your meeting has been scheduled!
              </Typography>
              
              <Box sx={{ 
                display: 'flex', 
                flexDirection: 'column', 
                alignItems: 'center',
                bgcolor: 'background.paper',
                p: 3,
                borderRadius: 2,
                boxShadow: 1,
                mt: 2,
                mb: 3
              }}>
                <Typography variant="subtitle1" gutterBottom>
                  Meeting Code:
                </Typography>
                <Box sx={{ 
                  display: 'flex', 
                  alignItems: 'center', 
                  justifyContent: 'center',
                  gap: 1,
                  mb: 2
                }}>
                  <Chip 
                    label={meetingCode}
                    color="primary"
                    size="large"
                    sx={{ fontSize: '1.2rem', py: 2.5, px: 1 }}
                  />
                  <IconButton 
                    onClick={handleCopyMeetingCode}
                    color="primary"
                    sx={{ ml: 1 }}
                  >
                    <ContentCopyIcon />
                  </IconButton>
                </Box>
                
                <Grid container spacing={2} sx={{ mt: 2, textAlign: 'left' }}>
                  <Grid item xs={12} sm={6}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <EventIcon color="primary" />
                      <Typography variant="body1">
                        {format(meetingDate, 'EEEE, MMMM d, yyyy')}
                      </Typography>
                    </Box>
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                      <AccessTimeIcon color="primary" />
                      <Typography variant="body1">
                        {format(meetingDate, 'h:mm a')} ({duration} minutes)
                      </Typography>
                    </Box>
                  </Grid>
                  {participants.length > 0 && (
                    <Grid item xs={12}>
                      <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                        <PersonAddIcon color="primary" sx={{ mt: 0.5 }} />
                        <Box>
                          <Typography variant="body1" gutterBottom>
                            Participants:
                          </Typography>
                          <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                            {participants.map((participant, index) => (
                              <Chip key={index} label={participant} size="small" />
                            ))}
                          </Box>
                        </Box>
                      </Box>
                    </Grid>
                  )}
                </Grid>
              </Box>
              
              <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                Share this code with participants to join the scheduled meeting
              </Typography>
            </Box>
          ) : (
            <Grid container spacing={3}>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Meeting Title"
                  variant="outlined"
                  value={meetingTitle}
                  onChange={(e) => setMeetingTitle(e.target.value)}
                  required
                />
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <LocalizationProvider dateAdapter={AdapterDateFns}>
                  <DateTimePicker
                    label="Date & Time"
                    value={meetingDate}
                    onChange={(newValue) => setMeetingDate(newValue)}
                    slotProps={{ textField: { fullWidth: true } }}
                    minDateTime={new Date()}
                  />
                </LocalizationProvider>
              </Grid>
              
              <Grid item xs={12} sm={6}>
                <FormControl fullWidth variant="outlined">
                  <InputLabel>Duration</InputLabel>
                  <Select
                    value={duration}
                    onChange={(e) => setDuration(e.target.value)}
                    label="Duration"
                  >
                    <MenuItem value={15}>15 minutes</MenuItem>
                    <MenuItem value={30}>30 minutes</MenuItem>
                    <MenuItem value={45}>45 minutes</MenuItem>
                    <MenuItem value={60}>1 hour</MenuItem>
                    <MenuItem value={90}>1.5 hours</MenuItem>
                    <MenuItem value={120}>2 hours</MenuItem>
                  </Select>
                </FormControl>
              </Grid>
              
              <Grid item xs={12}>
                <Typography variant="subtitle1" gutterBottom>
                  Add Participants (Optional)
                </Typography>
                <Box sx={{ display: 'flex', gap: 1 }}>
                  <TextField
                    fullWidth
                    label="Email Address"
                    variant="outlined"
                    value={newParticipant}
                    onChange={(e) => setNewParticipant(e.target.value)}
                    onKeyPress={(e) => e.key === 'Enter' && handleAddParticipant()}
                  />
                  <Button
                    variant="contained"
                    onClick={handleAddParticipant}
                    disabled={!newParticipant.trim()}
                  >
                    Add
                  </Button>
                </Box>
              </Grid>
              
              {participants.length > 0 && (
                <Grid item xs={12}>
                  <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                    {participants.map((participant, index) => (
                      <Chip
                        key={index}
                        label={participant}
                        onDelete={() => handleRemoveParticipant(participant)}
                      />
                    ))}
                  </Box>
                </Grid>
              )}
            </Grid>
          )}
        </DialogContent>
        
        <DialogActions sx={{ px: 3, py: 2 }}>
          {!meetingCode ? (
            <>
              <Button onClick={onClose} disabled={loading}>
                Cancel
              </Button>
              <Button
                variant="contained"
                onClick={handleSchedule}
                disabled={loading || !meetingTitle.trim()}
                startIcon={loading ? <CircularProgress size={20} /> : null}
              >
                {loading ? 'Scheduling...' : 'Schedule Meeting'}
              </Button>
            </>
          ) : (
            <Button variant="contained" onClick={onClose}>
              Done
            </Button>
          )}
        </DialogActions>
      </Dialog>
      
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </>
  );
};

export default ScheduleMeeting;