/**
 * Utility functions for notifications
 */

import { toast } from 'react-toastify';

/**
 * Default toast configuration
 */
const defaultToastConfig = {
  position: 'top-right',
  autoClose: 5000,
  hideProgressBar: false,
  closeOnClick: true,
  pauseOnHover: true,
  draggable: true,
  progress: undefined,
};

/**
 * Shows a success notification
 * @param {string} message - Notification message
 * @param {Object} config - Toast configuration override
 */
export const showSuccessNotification = (message, config = {}) => {
  toast.success(message, { ...defaultToastConfig, ...config });
};

/**
 * Shows an error notification
 * @param {string} message - Notification message
 * @param {Object} config - Toast configuration override
 */
export const showErrorNotification = (message, config = {}) => {
  toast.error(message, { ...defaultToastConfig, ...config });
};

/**
 * Shows an info notification
 * @param {string} message - Notification message
 * @param {Object} config - Toast configuration override
 */
export const showInfoNotification = (message, config = {}) => {
  toast.info(message, { ...defaultToastConfig, ...config });
};

/**
 * Shows a warning notification
 * @param {string} message - Notification message
 * @param {Object} config - Toast configuration override
 */
export const showWarningNotification = (message, config = {}) => {
  toast.warning(message, { ...defaultToastConfig, ...config });
};

/**
 * Shows a meeting notification
 * @param {Object} meeting - Meeting object
 * @param {string} type - Notification type ('upcoming', 'started', 'ended', 'reminder')
 */
export const showMeetingNotification = (meeting, type) => {
  if (!meeting) return;
  
  const title = meeting.title || 'Video Meeting';
  
  switch (type) {
    case 'upcoming':
      showInfoNotification(`Meeting "${title}" is coming up soon`, {
        autoClose: 8000,
      });
      break;
    case 'started':
      showSuccessNotification(`Meeting "${title}" has started`, {
        autoClose: 8000,
      });
      break;
    case 'ended':
      showInfoNotification(`Meeting "${title}" has ended`);
      break;
    case 'reminder':
      showWarningNotification(`Reminder: Meeting "${title}" starts in 5 minutes`, {
        autoClose: 10000,
      });
      break;
    case 'joined':
      showSuccessNotification(`You have joined "${title}"`);
      break;
    case 'left':
      showInfoNotification(`You have left "${title}"`);
      break;
    default:
      showInfoNotification(`Meeting notification: ${title}`);
  }
};

/**
 * Shows a notification for meeting actions
 * @param {string} action - Action performed ('created', 'updated', 'deleted', 'shared')
 * @param {Object} meeting - Meeting object
 */
export const showMeetingActionNotification = (action, meeting) => {
  if (!meeting) return;
  
  const title = meeting.title || 'Video Meeting';
  
  switch (action) {
    case 'created':
      showSuccessNotification(`Meeting "${title}" has been created successfully`);
      break;
    case 'updated':
      showSuccessNotification(`Meeting "${title}" has been updated successfully`);
      break;
    case 'deleted':
      showSuccessNotification(`Meeting "${title}" has been deleted`);
      break;
    case 'shared':
      showSuccessNotification(`Meeting "${title}" has been shared successfully`);
      break;
    case 'copied':
      showSuccessNotification(`Meeting code has been copied to clipboard`);
      break;
    default:
      showInfoNotification(`Meeting "${title}" action completed`);
  }
};

/**
 * Shows a notification for user actions
 * @param {string} action - Action performed ('login', 'logout', 'register', 'guest')
 * @param {Object} user - User object (optional)
 */
export const showUserActionNotification = (action, user = null) => {
  const username = user?.displayName || user?.email || 'User';
  
  switch (action) {
    case 'login':
      showSuccessNotification(`Welcome back, ${username}!`);
      break;
    case 'logout':
      showInfoNotification(`You have been logged out`);
      break;
    case 'register':
      showSuccessNotification(`Account created successfully. Welcome, ${username}!`);
      break;
    case 'guest':
      showInfoNotification(`You are using the app as a guest`);
      break;
    case 'profile_updated':
      showSuccessNotification(`Your profile has been updated successfully`);
      break;
    default:
      showInfoNotification(`User action completed`);
  }
};