/**
 * Utility functions for recording meetings
 */

/**
 * Recording states
 */
export const RecordingState = {
  INACTIVE: 'inactive',
  RECORDING: 'recording',
  PAUSED: 'paused',
  PROCESSING: 'processing',
  ERROR: 'error'
};

/**
 * Class for handling meeting recordings
 */
export class MeetingRecorder {
  constructor() {
    this.mediaRecorder = null;
    this.recordedChunks = [];
    this.stream = null;
    this.state = RecordingState.INACTIVE;
    this.startTime = null;
    this.pausedDuration = 0;
    this.pauseStartTime = null;
    this.onStateChange = null;
    this.onDataAvailable = null;
    this.onError = null;
  }

  /**
   * Starts recording
   * @param {MediaStream} stream - Stream to record
   * @param {Object} options - Recording options
   * @returns {Promise<boolean>} Success status
   */
  async start(stream, options = {}) {
    if (!stream || !stream.active) {
      this._handleError(new Error('Invalid stream provided'));
      return false;
    }

    try {
      this.stream = stream;
      const mimeType = this._getSupportedMimeType();
      
      const recorderOptions = {
        mimeType,
        videoBitsPerSecond: options.videoBitsPerSecond || 2500000,
        audioBitsPerSecond: options.audioBitsPerSecond || 128000
      };

      this.mediaRecorder = new MediaRecorder(stream, recorderOptions);
      this.recordedChunks = [];
      
      this.mediaRecorder.ondataavailable = (event) => {
        if (event.data.size > 0) {
          this.recordedChunks.push(event.data);
          if (this.onDataAvailable) {
            this.onDataAvailable(event.data);
          }
        }
      };

      this.mediaRecorder.onerror = (event) => {
        this._handleError(event.error);
      };

      this.mediaRecorder.start(options.timeslice || 1000);
      this.state = RecordingState.RECORDING;
      this.startTime = Date.now();
      this._notifyStateChange();
      
      return true;
    } catch (error) {
      this._handleError(error);
      return false;
    }
  }

  /**
   * Pauses recording
   * @returns {boolean} Success status
   */
  pause() {
    if (!this.mediaRecorder || this.state !== RecordingState.RECORDING) {
      return false;
    }

    try {
      this.mediaRecorder.pause();
      this.state = RecordingState.PAUSED;
      this.pauseStartTime = Date.now();
      this._notifyStateChange();
      return true;
    } catch (error) {
      this._handleError(error);
      return false;
    }
  }

  /**
   * Resumes recording
   * @returns {boolean} Success status
   */
  resume() {
    if (!this.mediaRecorder || this.state !== RecordingState.PAUSED) {
      return false;
    }

    try {
      this.mediaRecorder.resume();
      this.state = RecordingState.RECORDING;
      
      // Calculate paused duration
      if (this.pauseStartTime) {
        this.pausedDuration += (Date.now() - this.pauseStartTime);
        this.pauseStartTime = null;
      }
      
      this._notifyStateChange();
      return true;
    } catch (error) {
      this._handleError(error);
      return false;
    }
  }

  /**
   * Stops recording
   * @returns {Promise<Blob|null>} Recording blob or null if failed
   */
  async stop() {
    if (!this.mediaRecorder || 
        (this.state !== RecordingState.RECORDING && 
         this.state !== RecordingState.PAUSED)) {
      return null;
    }

    try {
      this.state = RecordingState.PROCESSING;
      this._notifyStateChange();
      
      // Create a promise that resolves when the mediaRecorder stops
      const stopPromise = new Promise((resolve) => {
        this.mediaRecorder.onstop = () => resolve();
      });
      
      this.mediaRecorder.stop();
      await stopPromise;
      
      const mimeType = this._getSupportedMimeType();
      const recordingBlob = new Blob(this.recordedChunks, { type: mimeType });
      
      this.state = RecordingState.INACTIVE;
      this._notifyStateChange();
      
      return recordingBlob;
    } catch (error) {
      this._handleError(error);
      return null;
    }
  }

  /**
   * Gets recording duration in milliseconds
   * @returns {number} Recording duration
   */
  getDuration() {
    if (!this.startTime) return 0;
    
    let duration = 0;
    if (this.state === RecordingState.PAUSED) {
      duration = (this.pauseStartTime - this.startTime) - this.pausedDuration;
    } else {
      duration = (Date.now() - this.startTime) - this.pausedDuration;
    }
    
    return Math.max(0, duration);
  }

  /**
   * Gets current recording state
   * @returns {string} Recording state
   */
  getState() {
    return this.state;
  }

  /**
   * Cleans up resources
   */
  cleanup() {
    if (this.mediaRecorder && this.state !== RecordingState.INACTIVE) {
      try {
        this.mediaRecorder.stop();
      } catch (error) {
        console.error('Error stopping media recorder during cleanup:', error);
      }
    }
    
    this.mediaRecorder = null;
    this.recordedChunks = [];
    this.stream = null;
    this.state = RecordingState.INACTIVE;
    this.startTime = null;
    this.pausedDuration = 0;
    this.pauseStartTime = null;
  }

  /**
   * Saves recording to file
   * @param {Blob} blob - Recording blob
   * @param {string} filename - Filename to save as
   */
  saveRecording(blob, filename = 'meeting-recording.webm') {
    if (!blob) return;
    
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    document.body.appendChild(a);
    a.style.display = 'none';
    a.href = url;
    a.download = filename;
    a.click();
    
    // Cleanup
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 100);
  }

  /**
   * Gets supported MIME type for recording
   * @returns {string} Supported MIME type
   * @private
   */
  _getSupportedMimeType() {
    const types = [
      'video/webm;codecs=vp9,opus',
      'video/webm;codecs=vp8,opus',
      'video/webm;codecs=h264,opus',
      'video/webm',
      'video/mp4'
    ];
    
    for (const type of types) {
      if (MediaRecorder.isTypeSupported(type)) {
        return type;
      }
    }
    
    return '';
  }

  /**
   * Handles recording errors
   * @param {Error} error - Error object
   * @private
   */
  _handleError(error) {
    console.error('Recording error:', error);
    this.state = RecordingState.ERROR;
    this._notifyStateChange();
    
    if (this.onError) {
      this.onError(error);
    }
  }

  /**
   * Notifies state change listeners
   * @private
   */
  _notifyStateChange() {
    if (this.onStateChange) {
      this.onStateChange(this.state);
    }
  }
}

/**
 * Checks if recording is supported in the current browser
 * @returns {boolean} True if recording is supported
 */
export const isRecordingSupported = () => {
  return typeof MediaRecorder !== 'undefined';
};

/**
 * Creates a filename for a recording
 * @param {string} meetingCode - Meeting code
 * @param {Date} date - Recording date
 * @returns {string} Filename
 */
export const createRecordingFilename = (meetingCode, date = new Date()) => {
  const formattedDate = date.toISOString().replace(/[:.]/g, '-').slice(0, 19);
  return `meeting-${meetingCode}-${formattedDate}.webm`;
};